INSERT INTO processing_purposes (id, code, name, name_hi, name_gu, description, description_hi, description_gu, legal_basis, is_mandatory, is_active) VALUES
(1, 'application_processing', 'Driving Licence Application Processing', 'ड्राइविंग लाइसेंस आवेदन प्रसंस्करण', 'ડ્રાઇવિંગ લાયસન્સ અરજી પ્રક્રિયા', 'Processing applicant information and documentation for RTO submission.', 'आरटीओ सबमिशन के लिए आवेदक की जानकारी और दस्तावेजों का प्रसंस्करण।', 'RTO સબમિશન માટે અરજદારની માહિતી અને દસ્તાવેજોની પ્રક્રિયા.', 'consent', 1, 1),
(2, 'identity_verification', 'Identity & Age Verification', 'पहचान एवं आयु सत्यापन', 'ઓળખ અને ઉંમર ચકાસણી', 'Verifying age and identity credentials to comply with Motor Vehicles Act.', 'मोटर वाहन अधिनियम के अनुपालन के लिए आयु और पहचान प्रमाण का सत्यापन।', 'મોટર વાહન અધિનિયમના પાલન માટે ઉંમર અને ઓળખ પુરાવાની ચકાસણી.', 'legal_requirement', 1, 1),
(3, 'user_account', 'Citizen Account Management', 'नागरिक खाता प्रबंधन', 'નાગરિક ખાતું સંચાલન', 'Maintaining authenticated user session, draft state, and security credentials.', 'प्रमाणीकृत उपयोगकर्ता सत्र, ड्राफ्ट स्थिति और सुरक्षा क्रेडेंशियल्स का रखरखाव।', 'પ્રમાણિત યુઝર સેશન, ડ્રાફ્ટ સ્થિતિ અને સુરક્ષા ઓળખપત્રોની જાળવણી.', 'legitimate_use', 1, 1),
(4, 'service_communication', 'Service Communication & Tracking Alerts', 'सेवा संचार एवं ट्रैकिंग अलर्ट', 'સેવા સંચાર અને ટ્રેકિંગ ચેતવણીઓ', 'Sending transactional SMS/email updates regarding application progress and test dates.', 'आवेदन की प्रगति और परीक्षण तिथियों के संबंध में लेनदेन संबंधी एसएमएस/ईमेल अपडेट भेजना।', 'અરજીની પ્રગતિ અને ટેસ્ટ તારીખો સંબંધિત ટ્રાન્ઝેક્શનલ એસએમએસ/ઇમેઇલ અપડેટ્સ મોકલવા.', 'consent', 1, 1),
(5, 'payment_processing', 'Fee Settlement & Payment Processing', 'शुल्क निपटान एवं भुगतान प्रसंस्करण', 'ફી પતાવટ અને ચુકવણી પ્રક્રિયા', 'Processing government and platform facilitation fees through authorized payment gateways.', 'अधिकृत भुगतान गेटवे के माध्यम से सरकारी और प्लेटफ़ॉर्म सुविधा शुल्क का प्रसंस्करण।', 'અધિકૃત પેમેન્ટ ગેટવે દ્વારા સરકારી અને પ્લેટફોર્મ સુવિધા ફીની પ્રક્રિયા.', 'contract', 1, 1),
(6, 'document_verification', 'Document Scrutiny & RTO Prep', 'दस्तावेज़ जांच एवं आरटीओ तैयारी', 'દસ્તાવેજ ચકાસણી અને RTO તૈયારી', 'Checking clarity, validity, and completeness of uploaded identity and address proofs.', 'अपलोड किए गए पहचान और पते के प्रमाणों की स्पष्टता, वैधता और पूर्णता की जांच करना।', 'અપલોડ કરેલા ઓળખ અને સરનામાના પુરાવાની સ્પષ્ટતા, માન્યતા અને પૂર્ણતાની ચકાસણી.', 'consent', 1, 1),
(7, 'security', 'Platform Security & Abuse Prevention', 'प्लेटफ़ॉर्म सुरक्षा एवं दुरुपयोग रोकथाम', 'પ્લેટફોર્મ સુરક્ષા અને દુરુપયોગ નિવારણ', 'Preventing unauthorized account access, DDoS attacks, and fraudulent bot submissions.', 'अनधिकृत खाता पहुंच, डीडीओएस हमलों और धोखाधड़ी वाले बॉट सबमिशन को रोकना।', 'અનધિકૃત એકાઉન્ટ એક્સેસ, DDoS હુમલા અને છેતરપિંડીયુક્ત બોટ સબમિશન અટકાવવા.', 'legal_requirement', 1, 1),
(8, 'legal_compliance', 'Statutory Record Keeping & DPDP Compliance', 'वैधानिक रिकॉर्ड कीपिंग एवं डीपीडीपी अनुपालन', 'વૈધાનિક રેકોર્ડ રાખવા અને DPDP પાલન', 'Maintaining audit trails and compliance records under DPDP Act 2023.', 'डीपीडीपी अधिनियम 2023 के तहत ऑडिट ट्रेल्स और अनुपालन रिकॉर्ड बनाए रखना।', 'DPDP એક્ટ 2023 હેઠળ ઓડિટ ટ્રેલ્સ અને પાલન રેકોર્ડ્સ જાળવવા.', 'legal_requirement', 1, 1),
(9, 'grievance_management', 'Grievance Redressal & Support', 'शिकायत निवारण एवं सहायता', 'ફરિયાદ નિવારણ અને સહાય', 'Resolving citizen grievances and exercising Data Principal statutory rights.', 'नागरिक शिकायतों का समाधान और डेटा प्रिंसिपल वैधानिक अधिकारों का प्रयोग करना।', 'નાગરિક ફરિયાદોનું નિરાકરણ અને ડેટા પ્રિન્સિપાલ વૈધાનિક અધિકારોનો ઉપયોગ કરવો.', 'legal_requirement', 1, 1),
(10, 'fraud_prevention', 'Fraud Prevention & Duplicate Detection', 'धोखाधड़ी रोकथाम एवं डुप्लिकेट पहचान', 'છેતરપિંડી નિવારણ અને ડુપ્લિકેટ શોધ', 'Detecting forged documents and repeated unauthorized application submissions.', 'जाली दस्तावेजों और बार-बार अनधिकृत आवेदन प्रस्तुतियों का पता लगाना।', 'બનાવટી દસ્તાવેજો અને વારંવાર અનધિકૃત અરજી સબમિશન શોધવા.', 'legitimate_use', 1, 1),
(11, 'analytics', 'Citizen Experience Analytics (Optional)', 'नागरिक अनुभव विश्लेषण (वैकल्पिक)', 'નાગરિક અનુભવ વિશ્લેષણ (વૈકલ્પિક)', 'Aggregated and privacy-preserving insights to improve portal usability and flow.', 'पोर्टल की उपयोगिता और प्रवाह को बेहतर बनाने के लिए समग्र और गोपनीयता-संरक्षण अंतर्दृष्टि।', 'પોર્ટલ ઉપયોગિતા અને પ્રવાહ સુધારવા માટે એકત્રિત અને ગોપનીયતા-સંરક્ષિત આંતરદૃષ્ટિ.', 'consent', 0, 1),
(12, 'marketing', 'Informational Updates & Tips (Optional)', 'सूचनात्मक अपडेट और युक्तियाँ (वैकल्पिक)', 'માહિતીપ્રદ અપડેટ્સ અને ટિપ્સ (વૈકલ્પિક)', 'Occasional alerts regarding new transport schemes and road safety advisories.', 'नई परिवहन योजनाओं और सड़क सुरक्षा सलाह के संबंध में सामयिक अलर्ट।', 'નવી પરિવહન યોજનાઓ અને માર્ગ સલામતી સલાહકારો અંગે સામયિક ચેતવણીઓ.', 'consent', 0, 1) ON CONFLICT DO NOTHING;
